var TIERS=[{upTo:10000,rate:0.05},{upTo:50000,rate:0.08},{upTo:Infinity,rate:0.12}];
function commission(sales, tiers){
  sales=+sales; if(!(sales>=0)) return {error:'销售额须非负'}; tiers=tiers||TIERS;
  var remaining=sales, prev=0, total=0;
  for(var i=0;i<tiers.length;i++){ var top=tiers[i].upTo; var band=Math.min(sales,top)-prev;
    if(band>0) total+=band*tiers[i].rate; prev=Math.min(sales,top); if(sales<=top) break; }
  return {amount:Math.round(total*100)/100, rate:Math.round(total/sales*10000)/100}; }
var EXPORTS={commission:commission, TIERS:TIERS};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CommissionForgePure = EXPORTS; }
